UPDATE experiment_handoff
   SET status = 'confirmed', updated_at = now()
 WHERE tenant_id = #{param1} AND experiment_id = #{param2}
   AND from_workcell_id = #{param3} AND to_workcell_id = #{param4}
   AND status IN ('configured', 'unknown')

UPDATE experiment_handoff
   SET intervention_record_id = #{param5}, manual_window_id = #{param6}
 WHERE tenant_id = #{param1} AND experiment_id = #{param2}
   AND from_workcell_id = #{param3} AND to_workcell_id = #{param4}
